INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 16, 'theory', 'Firewalls, Proxies, and NAT in Practice');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 0, 'What does the rule "accept packets in the ESTABLISHED state" mean in a stateful firewall?', '["Allow any new connections", "Block replies", "Allow only ICMP", "Allow replies to connections already opened from the inside"]', 3, 'This lets clients inside go out while new connections from outside are not accepted.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 1, 'The gateway forwards 8080 → 192.168.0.10:80, but it does not work from outside. The FORWARD policy is DROP. What do you need to allow in FORWARD?', '["The internal address 192.168.0.10 and port 80: DNAT fires before the filter", "The gateway''s public address and port 8080", "Only port 22", "Nothing: forwarding works by itself"]', 0, 'By the time of the FORWARD filter, the address and port have already been replaced with the internal ones.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 2, 'What does MASQUERADE do?', '["Replaces the destination address", "Encrypts traffic", "Rewrites the source address of internal packets to the address of the outgoing interface", "Blocks ports"]', 2, 'Replies come back through the translation table.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 3, 'Which rule between zones is sensible?', '["DMZ → LAN: allow everything", "Internet → DMZ: only the needed ports; DMZ → LAN: deny", "Internet → LAN: allow everything", "LAN → internet: deny"]', 1, 'Compromising a server in the DMZ does not give access to the internal network.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 16, 4, 'A client in the LAN contacts a LAN server by its public address and gets no reply. What is the cause?', '["The server replies to the client directly, while the client waits for a reply from the public address", "The server is down", "Port 53 is closed", "The certificate is out of date"]', 0, 'SNAT on the gateway for such traffic, or split DNS (hairpin NAT), helps.');
